711      <script>
712          // Theme Toggle
713          const themeToggleButton = document.getElementById('theme-toggle-button');
714          const body = document.body;
715  
716          // Theme preference will not be saved due to file:// origin restrictions in test harness.
717          // Default to dark theme if OS preference is dark, otherwise light.
718          if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
719              body.classList.add('dark-theme');
720          }
721  
722          themeToggleButton.addEventListener('click', () => {
723              body.classList.toggle('dark-theme');
724          });
725  
726          // Sticky Nav (already handled by CSS position: sticky)
727  
728          // Metrics Counter on Scroll
729          const metricsSection = document.querySelector('.metrics');
730          const metricItems = document.querySelectorAll('.metric-item h3');
731          let countersActivated = false;
732  
733          const animateCounter = (element, target) => {
734              let current = 0;
735              const duration = 2000; // 2 seconds
736              const increment = target / (duration / 10); // Update every 10ms
737  
738              const updateCounter = () => {
739                  if (current < target) {
740                      current += increment;
741                      element.textContent = Math.min(Math.round(current), target);
742                      requestAnimationFrame(updateCounter);
743                  } else {
744                      element.textContent = target;
745                  }
746              };
747              updateCounter();
748          };
749  
750          const observerOptions = {
751              root: null,
752              rootMargin: '0px',
753              threshold: 0.5 // Trigger when 50% of the section is visible
754          };
755  
756          const observer = new IntersectionObserver((entries, observer) => {
757              entries.forEach(entry => {
758                  if (entry.isIntersecting && !countersActivated) {
759                      metricItems.forEach(item => {
760                          const target = parseInt(item.dataset.target);
761                          animateCounter(item, target);
762                      });
763                      countersActivated = true;
764                      observer.unobserve(entry.target); // Stop observing once activated
765                  }
766              });
767          }, observerOptions);
768  
769          if (metricsSection) {
770              observer.observe(metricsSection);
771          }
772  
773  
774          // FAQ Accordion
775          const accordionHeaders = document.querySelectorAll('.accordion-header');
776  
777          accordionHeaders.forEach(header => {
778              header.addEventListener('click', () => {
779                  const accordionItem = header.parentElement;
780                  const accordionContent = header.nextElementSibling;
781  
782                  // Toggle 'active' class on header
783                  header.classList.toggle('active');
784  
785                  // Toggle 'active' class on content and adjust max-height
786                  if (accordionContent.classList.contains('active')) {
787                      accordionContent.classList.remove('active');
788                      accordionContent.style.maxHeight = '0';
789                      accordionContent.style.padding = '0 20px'; // Reset padding
790                  } else {
791                      accordionContent.classList.add('active');
792                      accordionContent.style.maxHeight = accordionContent.scrollHeight + 'px';
793                      accordionContent.style.padding = '20px'; // Apply padding
794                  }
795              });
796          });
797  
798          // Adjust max-height on window resize for active accordion items
799          window.addEventListener('resize', () => {
800              document.querySelectorAll('.accordion-content.active').forEach(content => {
801                  content.style.maxHeight = content.scrollHeight + 'px';
802              });
803          });
804      </script>
